import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
/*eslint-disable*/
import AddCategory from "@/components/SettingsDialogs/AddCategory.vue";
import DeleteCategories from "@/components/SettingsDialogs/DeleteCategories.vue";
import EditCategory from "@/components/SettingsDialogs/EditCategory.vue";
import SnackBar from "@/components/SnackBar.vue";
import AddSubcategories from "@/components/SettingsDialogs/AddSubcategories.vue";
import { items_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  components: {
    SnackBar,
    DeleteCategories,
    EditCategory,
    AddCategory,
    AddSubcategories
  },
  mixins: [get_all_org_users],
  data() {
    return {
      SnackBarComponent: {},
      categoriesEddition: false,
      categoriesdeletion: false,
      categoriesAddition: false,
      tableLoading: false,
      componentCheck: 0,
      categoriesItem: {},
      categoriessubAddition: false,
      searchQuery: "",
      currentPage: 1,
      itemsPerPage: 10,
      sortBy: [{
        key: "category_name",
        order: "asc"
      }],
      categoriesHeaders: [{
        title: "Category Name",
        value: "category_name",
        sortable: true,
        align: "start"
      }, {
        title: "Created By",
        value: "category_created_by",
        sortable: true,
        align: "start"
      }, {
        title: "Actions",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      categoriesRecords: [],
      fixed: true,
      expanded: [],
      allUSersNames: [],
      singleExpand: true,
      categoryPrefix: "",
      subcategoryName: "",
      rowInfo: {},
      windowHeight: 0
    };
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.categoriesRecords;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.categoriesRecords.filter(item => item.category_name && item.category_name.toLowerCase().includes(searchTerm) || item.category_description && item.category_description.toLowerCase().includes(searchTerm) || item.category_created_by && this.fetch_user_name(item.category_created_by).toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage(newVal) {
      // When the page changes, scroll to top of the card container
      this.$nextTick(() => {
        const cardContainer = document.querySelector(".card-container");
        if (cardContainer) {
          cardContainer.scrollIntoView({
            behavior: "smooth",
            block: "start"
          });
        } else {
          // Fallback to scrolling to top of page
          window.scrollTo({
            top: 0,
            behavior: "smooth"
          });
        }
      });
    }
  },
  async created() {
    this.windowHeight = window.innerHeight - 380;
    await this.fetch_categories();
    await this.get_all_org_users();
    this.allUSersNames = this.orgUsers;
  },
  methods: {
    add_categories() {
      this.componentCheck = 5;
      this.categoriesAddition = true;
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      if (value == "SYSTEM") {
        name = value;
      }
      return name;
    },
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    handle_row_click(item) {
      this.componentCheck = 4;
      this.categoriessubAddition = true;
      this.rowInfo = item;
    },
    open_editDailog(item) {
      this.categoriesItem = item;
      this.componentCheck = 2;
      this.categoriesEddition = true;
    },
    open_deleteDailog(item) {
      this.categoriesItem = item;
      this.componentCheck = 1;
      this.categoriesdeletion = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.categoriesdeletion = false;
      this.categoriesEddition = false;
      this.categoriesAddition = false;
      this.fetch_categories();
    },
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "category_name" || key === "category_description" || key === "category_created_by") {
        return value.toLowerCase();
      }
      if (key === "category_created_on") {
        return new Date(parseInt(value) * 1000).getTime();
      }
      return value;
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.currentPage = 1; // Reset to first page when sorting changes
    },
    async fetch_categories() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(items_categories, {
          input: {
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.items_categories);
        this.categoriesRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          // Check multiple possible data structures
          let categoriesData = null;
          if (response.data && Array.isArray(response.data)) {
            categoriesData = response.data;
          } else if (response.categories && Array.isArray(response.categories)) {
            categoriesData = response.categories;
          } else if (response.result && Array.isArray(response.result)) {
            categoriesData = response.result;
          } else if (response.items && Array.isArray(response.items)) {
            categoriesData = response.items;
          } else {
            categoriesData = [];
          }
          this.categoriesRecords = categoriesData || [];
          this.tableLoading = false;
        } else {
          this.categoriesRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        // console.error("Error fetching categories:", error);
        this.categoriesRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    goBack() {
      this.$emit('backAction');
    }
  }
};
